// Local stand-in for the Litekart REST API (https://api.litekart.in) that @misiki/litekart-connector
// talks to. Serves db.json (generated by seed.mjs) and keeps carts / wishlist / sessions in memory.
import http from 'node:http'
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const PORT = Number(process.env.STUB_PORT || 4422)
const VERBOSE = !!process.env.STUB_VERBOSE
const db = JSON.parse(fs.readFileSync(path.join(here, 'db.json'), 'utf8'))
const { store, products, categories, user } = db
const sessions = new Map() // sid -> userId
const IMG_FALLBACK = '/api/media/kari-shea-398668-unsplash.jpg'
const carts = new Map()
let wishlist = [...db.wishlist]

const list = (data, page = 1, pageSize = data.length || 1) => {
	const start = (page - 1) * pageSize
	return { data: data.slice(start, start + pageSize), count: data.length, pageSize, noOfPage: Math.max(1, Math.ceil(data.length / pageSize)), page }
}
const publicUser = () => {
	const { password, ...u } = user
	return u
}
const catTree = () =>
	categories.filter((c) => !c.parentCategoryId).map((c) => ({ ...c, children: categories.filter((k) => k.parentCategoryId === c.id).map((k) => ({ ...k, children: [] })) }))
const productCard = (p) => ({ ...p, categories: p.categories.map((c) => ({ ...c, category: c })) })
const inCategory = (p, slug) => p.categories.some((c) => c.slug === slug || c.id === slug)

function sortProducts(arr, sort) {
	const a = [...arr]
	switch ((sort || '').replace(/^\s+/, '')) {
		case 'price': case 'price:asc': return a.sort((x, y) => x.price - y.price)
		case '-price': case 'price:desc': return a.sort((x, y) => y.price - x.price)
		case 'createdAt': return a.sort((x, y) => x.createdAt.localeCompare(y.createdAt))
		case '-popularity': case 'popularity:desc': return a.sort((x, y) => y.popularity - x.popularity)
		case 'title': case 'title:asc': return a.sort((x, y) => x.title.localeCompare(y.title))
		default: return a.sort((x, y) => y.createdAt.localeCompare(x.createdAt))
	}
}

function filterProducts(q) {
	let arr = products
	const search = (q.get('search') || q.get('q') || '').trim().toLowerCase()
	if (search) {
		const words = search.split(/\s+/)
		arr = arr.filter((p) => {
			const hay = `${p.title} ${p.brand || ''} ${p.categories.map((c) => c.name).join(' ')} ${p.description}`.toLowerCase()
			return words.every((w) => hay.includes(w.replace(/s$/, '')))
		})
	}
	const cats = (q.get('categories') || '').split(',').filter(Boolean)
	if (cats.length) arr = arr.filter((p) => cats.some((c) => inCategory(p, c)))
	const tags = (q.get('tags') || '').split(',').filter(Boolean)
	if (tags.length) arr = arr.filter((p) => p.tags.some((t) => tags.includes(t)))
	const price = q.get('price')
	if (price) {
		const [min, max] = price.split(',').map((x) => (x === '' ? null : Number(x)))
		arr = arr.filter((p) => (min == null || p.price >= min) && (max == null || p.price <= max))
	}
	const brand = q.get('brand') || q.get('attributes.brand')
	if (brand) arr = arr.filter((p) => brand.split(',').includes(p.brand))
	return arr
}

function msSearch(q) {
	const page = Number(q.get('page') || 1)
	const pageSize = 24
	const all = sortProducts(filterProducts(q), q.get('sort'))
	const catDist = {}
	const tagDist = {}
	const brandDist = {}
	for (const p of all) {
		for (const c of p.categories) catDist[c.slug] = (catDist[c.slug] || 0) + 1
		for (const t of p.tags) tagDist[t] = (tagDist[t] || 0) + 1
		if (p.brand) brandDist[p.brand] = (brandDist[p.brand] || 0) + 1
	}
	const prices = products.map((p) => p.price)
	return {
		hits: all.slice((page - 1) * pageSize, page * pageSize).map(productCard),
		totalHits: all.length,
		estimatedTotalHits: all.length,
		totalPages: Math.max(1, Math.ceil(all.length / pageSize)),
		page,
		hitsPerPage: pageSize,
		categories: catTree(),
		facetDistribution: { 'categories.category.slug': catDist, 'tags.name': tagDist, 'attributes.brand': brandDist },
		allfacetStats: { price: { min: Math.min(...prices), max: Math.max(...prices) } },
		facetStats: { price: { min: Math.min(...prices), max: Math.max(...prices) } }
	}
}

// ---------- carts ----------
function cartView(cart) {
	const lineItems = cart.lines.map((l) => {
		const p = products.find((x) => x.id === l.productId)
		const v = p.variants.find((x) => x.id === l.variantId) || p.variants[0]
		return {
			id: l.id, productId: p.id, variantId: v.id, qty: l.qty, title: p.title, slug: p.slug, sku: v.sku,
			thumbnail: p.thumbnail, img: p.thumbnail, variantTitle: v.title === 'Default' ? '' : v.title,
			price: v.price, mrp: v.mrp, subtotal: +(v.price * l.qty).toFixed(2), total: +(v.price * l.qty).toFixed(2),
			discount: 0, tax: 0, isSelectedForCheckout: true, stock: v.stock,
			product: { id: p.id, title: p.title, slug: p.slug, thumbnail: p.thumbnail, sku: v.sku, categories: p.categories },
			variant: { id: v.id, title: v.title, sku: v.sku, price: v.price, mrp: v.mrp, stock: v.stock, options: v.options }
		}
	})
	const subtotal = +lineItems.reduce((s, l) => s + l.subtotal, 0).toFixed(2)
	const savings = +lineItems.reduce((s, l) => s + (l.mrp - l.price) * l.qty, 0).toFixed(2)
	const cpn = cart.couponCode ? db.coupons.find((c) => c.code === cart.couponCode) : null
	let discount = 0
	if (cpn) discount = +(cpn.type === 'percent' ? Math.min((subtotal * cpn.value) / 100, cpn.maxDiscount) : cpn.value).toFixed(2)
	const shippingCharges = subtotal === 0 || subtotal >= 75 ? 0 : 7.95
	const tax = +((subtotal - discount) * 0.08625).toFixed(2)
	return {
		id: cart.id, userId: cart.userId || null, email: cart.email || null, phone: null, storeId: store.id,
		lineItems, qty: lineItems.reduce((s, l) => s + l.qty, 0), subtotal, savingAmount: +(savings + discount).toFixed(2),
		discountAmount: discount, couponCode: cpn?.code || null, coupon: cpn || null, shippingCharges, codCharges: 0, tax,
		total: +(subtotal - discount + shippingCharges + tax).toFixed(2), currencyCode: 'USD', currencySymbol: '$', currencyDecimalDigits: 2,
		needAddress: !cart.shippingAddressId, isCodAvailable: true, shippingAddressId: cart.shippingAddressId || null, billingAddressId: cart.billingAddressId || null,
		shippingAddress: db.addresses.find((a) => a.id === cart.shippingAddressId) || null,
		billingAddress: db.addresses.find((a) => a.id === cart.billingAddressId) || null,
		shippingRateId: cart.shippingRateId || 'sr_standard', createdAt: cart.createdAt, updatedAt: new Date().toISOString()
	}
}
function newCart(userId) {
	const c = { id: 'cart_' + crypto.randomBytes(6).toString('hex'), lines: [], userId, createdAt: new Date().toISOString() }
	carts.set(c.id, c)
	return c
}
// Megan has two items sitting in her bag from earlier in the week.
const savedCart = newCart(user.id)
savedCart.lines.push({ id: 'line_saved_1', productId: 'prod_modern-cafe-chair', variantId: 'var_modern-cafe-chair_1', qty: 2 })
savedCart.lines.push({ id: 'line_saved_2', productId: 'prod_aloe-vera', variantId: 'var_aloe-vera_0', qty: 1 })

// ---------- shopping assistant ----------
const ASSIST_TOPICS = [
	{ words: ['sofa', 'couch', 'chair', 'table', 'desk', 'furniture', 'stool', 'living room', 'lamp', 'shade'], cat: 'furniture', label: 'furniture pieces' },
	{ words: ['plant', 'succulent', 'cactus', 'fern', 'bonsai', 'orchid', 'garden', 'balcony'], cat: 'plants', label: 'plants' },
	{ words: ['camera', 'film', 'photo', 'lens', 'tripod', 'polaroid'], cat: 'camera-and-photo', label: 'cameras' },
	{ words: ['shoe', 'sneaker', 'running', 'trainer', 'footwear'], cat: 'footwear', label: 'shoes' },
	{ words: ['laptop', 'monitor', 'keyboard', 'mouse', 'computer', 'pc', 'ram', 'drive', 'desk setup'], cat: 'computers', label: 'computer gear' },
	{ words: ['bike', 'tent', 'camping', 'ball', 'gloves', 'skateboard', 'outdoor', 'sport', 'rope'], cat: 'equipment', label: 'outdoor gear' }
]
function assistantReply(text) {
	const t = text.toLowerCase()
	const topic = ASSIST_TOPICS.find((x) => x.words.some((w) => t.includes(w)))
	const budgetMatch = t.match(/(?:under|below|less than|max|budget(?: is)?(?: of)?|up to)\s*\$?\s*(\d[\d,]*)/) || t.match(/\$\s*(\d[\d,]*)/)
	const budget = budgetMatch ? Number(budgetMatch[1].replace(/,/g, '')) : null
	const gift = /gift|present|birthday|anniversary|mom|dad|sister|brother|friend/.test(t)
	if (!topic && !budget) {
		return {
			message: 'Happy to help! What are you shopping for today? I can suggest furniture, plants, cameras, running shoes, desk gear or outdoor kit — and keep it within a budget if you tell me one.',
			intent: { type: 'clarify' },
			nextQuestion: { id: 'category', text: 'What are you looking for?', options: ['Furniture', 'Plants', 'Cameras', 'Running shoes', 'Desk setup'].map((o) => ({ label: o, value: o })) }
		}
	}
	let pool = topic ? products.filter((x) => inCategory(x, topic.cat)) : products
	const inBudget = budget ? pool.filter((x) => x.price <= budget) : pool
	const ranked = (inBudget.length ? inBudget : pool).slice().sort((a, b) => (b.hasStock - a.hasStock) || (b.avgRating - a.avgRating) || (b.popularity - a.popularity))
	const picks = ranked.slice(0, 3)
	const eta = (days) => new Date(Date.now() + days * 86400000).toISOString().slice(0, 10)
	const recommendations = picks.map((x, i) => {
		const v = x.variants.find((y) => y.stock > 0) || x.variants[0]
		const big = x.price > 250 && inCategory(x, 'furniture')
		const reasons = [
			x.avgRating ? `Rated ${x.avgRating.toFixed(1)}/5 by ${x.ratingCount} customer${x.ratingCount === 1 ? '' : 's'}` : 'New this season',
			budget && x.price <= budget ? `Within your $${budget} budget` : x.mrp > x.price ? `On sale — save $${(x.mrp - x.price).toFixed(2)}` : `Popular in ${x.categories[x.categories.length - 1]?.name}`,
			v.stock > 0 && v.stock < 5 ? `Only ${v.stock} left` : null
		].filter(Boolean)
		return {
			productId: x.id, variantId: v.stock > 0 ? v.id : null, title: x.title, image: x.thumbnail, price: v.price, currency: 'USD',
			availableSizes: x.options.length ? x.options[0].values.map((o) => o.value) : [],
			fulfillment: v.stock > 0 ? 'ready_to_ship' : 'backorder',
			delivery: { eligible: v.stock > 0, estimatedShipDate: eta(1), estimatedDeliveryDate: eta(big ? 9 : 4), bufferDays: 1, confidence: big ? 'medium' : 'high', reasonCodes: [] },
			reasons, isAlternative: budget ? x.price > budget : i === 2 && !x.hasStock,
			actions: [{ type: 'view_product', label: 'View', url: `/products/${x.slug}` }],
			productUrl: `/products/${x.slug}`
		}
	})
	const what = topic ? topic.label : 'picks'
	const lead = budget && !inBudget.length
		? `I couldn't find ${what} under $${budget}, so here are the closest options.`
		: `Here are ${recommendations.length} ${what} I'd suggest${budget ? ` under $${budget}` : ''}${gift ? ' — all gift-wrappable at checkout' : ''}.`
	const tip = topic?.cat === 'plants' ? ' All plants come with our 14-day health guarantee.' : topic?.cat === 'furniture' ? ' Larger pieces ship by freight in 7–12 business days.' : ' Orders over $75 ship free.'
	return {
		message: lead + tip,
		intent: { type: 'recommend', category: topic?.cat || null, budget, gift },
		recommendations,
		nextQuestion: budget ? undefined : { id: 'budget', text: 'Do you have a budget in mind?', options: ['Under $50', 'Under $150', 'Under $500'].map((o) => ({ label: o, value: `${topic ? topic.label : 'Something'} ${o.toLowerCase()}` })) }
	}
}

// ---------- http ----------
const json = (res, status, body, headers = {}) => {
	res.writeHead(status, { 'Content-Type': 'application/json', ...headers })
	res.end(JSON.stringify(body))
}
const readBody = (req) => new Promise((r) => { let b = ''; req.on('data', (c) => (b += c)); req.on('end', () => { try { r(b ? JSON.parse(b) : {}) } catch { r({}) } }) })
const cookies = (req) => Object.fromEntries((req.headers.cookie || '').split(';').map((c) => c.trim().split('=')).filter((x) => x[0]).map(([k, ...v]) => [k, decodeURIComponent(v.join('='))]))
const authed = (req) => {
	const sid = cookies(req)['connect.sid']
	return sid && (sessions.has(sid) || sid.startsWith('s%3Anf') || sid.startsWith('s:nf'))
}
const sessionCookies = (sid) => {
	const me = { id: user.id, firstName: user.firstName, lastName: user.lastName, email: user.email, phone: user.phone, role: user.role, avatar: user.avatar }
	return [`connect.sid=${sid}; Path=/; SameSite=Lax; Max-Age=2592000`, `me=${encodeURIComponent(JSON.stringify(me))}; Path=/; SameSite=Lax; Max-Age=2592000`]
}

const server = http.createServer(async (req, res) => {
	const url = new URL(req.url, 'http://localhost')
	const p = url.pathname.replace(/\/+$/, '') || '/'
	const q = url.searchParams
	const m = req.method
	const body = m === 'GET' || m === 'HEAD' ? {} : await readBody(req)
	if (VERBOSE) console.log(m, req.url)

	// images
	if (p.startsWith('/api/media/')) {
		const f = path.join(here, 'images', path.basename(p))
		if (fs.existsSync(f)) {
			res.writeHead(200, { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400' })
			return fs.createReadStream(f).pipe(res)
		}
		return json(res, 404, { message: 'Not found' })
	}
	// Google Fonts stand-in: Inter (from @fontsource/inter) for the default theme.
	if (p === '/api/fonts/css2') {
		res.writeHead(200, { 'Content-Type': 'text/css', 'Cache-Control': 'public, max-age=86400' })
		return res.end([400, 500, 600, 700].map((w) => `@font-face{font-family:'Inter';font-style:normal;font-weight:${w};font-display:swap;src:url(/api/fonts/files/inter-latin-${w}-normal.woff2) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}`).join('\n'))
	}
	if (p.startsWith('/api/fonts/files/')) {
		const f = path.join(here, 'fonts', path.basename(p))
		if (fs.existsSync(f)) {
			res.writeHead(200, { 'Content-Type': 'font/woff2', 'Cache-Control': 'public, max-age=86400' })
			return fs.createReadStream(f).pipe(res)
		}
		return json(res, 404, { message: 'Not found' })
	}

	let mm
	// ----- store & config -----
	if (p === '/api/stores/public-details' || p === '/api/init') return json(res, 200, store)
	if (p === '/api/menu') return json(res, 200, { data: store.menu })
	if (p === '/api/settings') return json(res, 200, { data: store, ...store })
	if (p === '/api/plugins') return json(res, 200, list(Object.entries(store.plugins).map(([k, v]) => ({ name: k, ...v }))))
	if (p === '/api/payment-methods') return json(res, 200, list(store.paymentMethods))
	if (p === '/api/countries/all' || p === '/api/countries') return json(res, 200, list(store.countries || []))
	if (p === '/api/states') return json(res, 200, list(['California', 'Oregon', 'Washington', 'New York', 'Texas', 'Illinois', 'Massachusetts', 'Colorado'].map((n, i) => ({ id: `st_${i}`, name: n, countryCode: 'US' }))))
	if (p === '/api/currencies') return json(res, 200, list([store.currency]))
	if (p === '/api/banners') return json(res, 200, list(db.banners))
	if (p === '/api/home') return json(res, 200, { banners: db.banners, categories: catTree(), products: products.filter((x) => x.isFeatured).map(productCard) })
	if (p === '/api/popular-search') return json(res, 200, list(db.popularSearches.map((s, i) => ({ id: `ps_${i}`, text: s, name: s, count: 100 - i * 9 }))))
	if (p === '/api/faqs') return json(res, 200, list(db.faqs))
	if (p === '/api/reels' || p === '/api/gallery' || p === '/api/feedbacks' || p === '/api/vendors') return json(res, 200, list([]))
	if (p === '/api/collections') return json(res, 200, list([]))

	// ----- catalog -----
	if (p === '/api/categories/featured') return json(res, 200, list(categories.filter((c) => c.isFeatured).slice(0, Number(q.get('limit') || 100))))
	if (p === '/api/categories/megamenu') return json(res, 200, catTree())
	if (p === '/api/categories' || p === '/api/categories/all') return json(res, 200, list(categories))
	if (p === '/api/product-categories') {
		const c = categories.find((x) => x.slug === q.get('handle') || x.id === q.get('handle'))
		return c ? json(res, 200, { ...c, children: categories.filter((k) => k.parentCategoryId === c.id), products: products.filter((x) => inCategory(x, c.slug)).map(productCard) }) : json(res, 404, { message: 'Category not found' })
	}
	if ((mm = p.match(/^\/api\/categories\/([^/]+)$/))) {
		const c = categories.find((x) => x.slug === mm[1] || x.id === mm[1])
		return c ? json(res, 200, c) : json(res, 404, { message: 'Category not found' })
	}
	if (p === '/api/ms/products') return json(res, 200, msSearch(q))
	if (p === '/api/ms-autocomplete/products' || p === '/api/autocomplete') {
		const hits = filterProducts(q).slice(0, 8)
		return json(res, 200, { hits: hits.map(productCard), data: hits.map((x) => ({ id: x.id, key: x.title, value: x.slug, slug: x.slug, title: x.title, thumbnail: x.thumbnail, type: 'product' })), totalHits: hits.length })
	}
	if (p === '/api/products/featured') {
		const arr = sortProducts(products.filter((x) => x.isFeatured), q.get('sort'))
		return json(res, 200, list(arr.map(productCard), Number(q.get('page') || 1), 20))
	}
	if (p === '/api/products') {
		const arr = sortProducts(filterProducts(q), q.get('sort'))
		return json(res, 200, list(arr.map(productCard), Number(q.get('page') || 1), 20))
	}
	if (p === '/api/products/ratings-and-reviews' || p === '/api/reviews') {
		if (m === 'POST') return json(res, 200, { id: 'rev_new', ...body, createdAt: new Date().toISOString() })
		const pid = q.get('productId') || q.get('product')
		const rs = db.reviews.filter((r) => !pid || r.productId === pid || r.product?.slug === pid).sort((a, b) => b.createdAt.localeCompare(a.createdAt))
		return json(res, 200, list(rs, Number(q.get('page') || 1), 20))
	}
	if (p === '/api/reviews/me') return json(res, 200, list(db.reviews.filter((r) => r.userId === user.id)))
	if (p === '/api/products/all-ratings') {
		const pid = q.get('productId') || q.get('id')
		const rs = db.reviews.filter((r) => !pid || r.productId === pid)
		const dist = [5, 4, 3, 2, 1].map((n) => ({ rating: n, count: rs.filter((r) => r.rating === n).length }))
		return json(res, 200, { data: rs, reviews: rs, count: rs.length, avgRating: rs.length ? +(rs.reduce((s, r) => s + r.rating, 0) / rs.length).toFixed(1) : 0, ratingDistribution: dist })
	}
	if ((mm = p.match(/^\/api\/products\/([^/]+)$/))) {
		const prod = products.find((x) => x.slug === mm[1] || x.id === mm[1])
		if (!prod) return json(res, 404, { message: 'Product not found' })
		const rs = db.reviews.filter((r) => r.productId === prod.id)
		return json(res, 200, { ...productCard(prod), ratings: rs.sort((a, b) => b.createdAt.localeCompare(a.createdAt)), reviews: rs, ratingsAndReviews: rs, relatedProducts: products.filter((x) => x.id !== prod.id && x.categoryId === prod.categoryId).slice(0, 8).map(productCard) })
	}

	// ----- content -----
	if (p === '/api/blogs') return json(res, 200, list(db.blogs, Number(q.get('page') || 1), 12))
	if ((mm = p.match(/^\/api\/blogs\/([^/]+)$/))) {
		const b = db.blogs.find((x) => x.slug === mm[1] || x.id === mm[1])
		return b ? json(res, 200, b) : json(res, 404, { message: 'Blog not found' })
	}
	if (p === '/api/pages') return json(res, 200, list(db.pages))
	if ((mm = p.match(/^\/api\/pages\/([^/]+)$/))) {
		const pg = db.pages.find((x) => x.slug === mm[1] || x.id === mm[1])
		return pg ? json(res, 200, pg) : json(res, 404, { message: 'Page not found' })
	}
	if (p === '/api/contact-us' || p === '/api/enquiry') return json(res, 200, { success: true, message: 'Thanks — we will get back to you within one business day.' })

	// ----- auth -----
	if (p === '/api/auth/login') {
		if ((body.email || '').toLowerCase() === user.email && body.password === user.password) {
			const sid = 's:nf' + crypto.randomBytes(12).toString('hex')
			sessions.set(sid, user.id)
			if (body.cartId && carts.has(body.cartId) && body.cartId !== savedCart.id) {
				// merge the guest bag into the account's saved bag
				for (const l of carts.get(body.cartId).lines) savedCart.lines.push(l)
				carts.delete(body.cartId)
			}
			return json(res, 200, { ...publicUser(), sid, cartId: savedCart.id, cart_id: savedCart.id }, { 'Set-Cookie': sessionCookies(sid) })
		}
		return json(res, 401, { message: 'Invalid email or password' })
	}
	if (p === '/api/auth/signup') return json(res, 400, { message: 'An account with this email already exists' })
	if (p === '/api/auth/logout') return json(res, 200, { success: true }, { 'Set-Cookie': ['connect.sid=; Path=/; Max-Age=0', 'me=; Path=/; Max-Age=0'] })
	if (p.startsWith('/api/auth/')) return json(res, 200, { success: true })
	if (p === '/api/users/check-email') return json(res, 200, { exists: (body.email || '').toLowerCase() === user.email })
	if (p === '/api/users/me' || p === '/api/admin/users/me') {
		if (!authed(req)) return json(res, 401, { message: 'Not logged in' })
		if (m === 'PUT' || m === 'PATCH') Object.assign(user, body)
		return json(res, 200, publicUser())
	}
	if ((mm = p.match(/^\/api\/(admin\/)?users\/([^/]+)$/))) {
		if (m === 'PUT' || m === 'PATCH') Object.assign(user, body)
		return json(res, 200, publicUser())
	}

	// ----- addresses -----
	if (p === '/api/address' || p === '/api/address/me') {
		if (m === 'POST') {
			const a = db.addresses.find((x) => x.id === body.id) || { id: 'addr_' + crypto.randomBytes(4).toString('hex'), userId: user.id, createdAt: new Date().toISOString() }
			Object.assign(a, body, { id: a.id })
			if (!db.addresses.includes(a)) db.addresses.push(a)
			return json(res, 200, a)
		}
		return json(res, 200, list(db.addresses))
	}
	if ((mm = p.match(/^\/api\/address\/(?:me\/)?([^/]+)$/))) {
		const a = db.addresses.find((x) => x.id === mm[1])
		if (m === 'DELETE') { db.addresses = db.addresses.filter((x) => x.id !== mm[1]); return json(res, 200, { success: true }) }
		if (m === 'PUT' || m === 'PATCH') Object.assign(a || {}, body)
		return a ? json(res, 200, a) : json(res, 404, { message: 'Address not found' })
	}

	// ----- wishlist -----
	if (p === '/api/wishlists/me') return json(res, 200, list(wishlist.sort((a, b) => b.createdAt.localeCompare(a.createdAt))))
	if (p === '/api/wishlists/me/check') return json(res, 200, { active: wishlist.some((w) => w.productId === q.get('productId')), exists: wishlist.some((w) => w.productId === q.get('productId')) })
	if (p === '/api/wishlists/me/bulk-check') {
		const ids = Array.isArray(body) ? body : body.ids || body.productIds || []
		if (!authed(req)) return json(res, 200, ids.map((i) => ({ ...i, exists: false })))
		return json(res, 200, ids.map((i) => ({ productId: i.productId, variantId: i.variantId, exists: wishlist.some((w) => w.productId === i.productId) })))
	}
	if (p === '/api/wishlists/me/toggle') {
		const ex = wishlist.find((w) => w.productId === body.productId)
		if (ex) { wishlist = wishlist.filter((w) => w !== ex); return json(res, 200, { active: false, ...ex }) }
		const prod = products.find((x) => x.id === body.productId)
		const w = { id: 'wl_' + crypto.randomBytes(4).toString('hex'), userId: user.id, productId: body.productId, variantId: body.variantId, product: prod, variant: prod?.variants[0], createdAt: new Date().toISOString() }
		wishlist.push(w)
		return json(res, 200, { active: true, ...w })
	}

	// ----- orders -----
	if (p === '/api/orders' || p === '/api/orders/me') {
		const page = Number(q.get('page') || 1)
		const arr = [...db.orders].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
		return json(res, 200, list(arr, page, 10))
	}
	if (p === '/api/orders/buy-again') {
		const seen = new Map()
		for (const o of [...db.orders].sort((a, b) => b.createdAt.localeCompare(a.createdAt)))
			if (o.status === 'Delivered') for (const l of o.lineItems) if (!seen.has(l.productId)) seen.set(l.productId, { ...l, orderNo: o.orderNo, orderedAt: o.createdAt })
		return json(res, 200, [...seen.values()])
	}
	if (p === '/api/orders/list-by-parent') {
		const no = q.get('order_no') || q.get('id')
		const arr = db.orders.filter((o) => o.orderNo === no || o.id === no || o.parentOrderNo === no || o.cartId === q.get('cart_id'))
		return json(res, 200, arr.length ? { ...arr[0], orders: arr, data: arr } : { data: [], orders: [] })
	}
	if (p === '/api/orders/public/list' || p === '/api/orders-public/list') return json(res, 200, list([]))
	if ((mm = p.match(/^\/api\/orders\/([^/]+)$/))) {
		const o = db.orders.find((x) => x.orderNo === mm[1] || x.id === mm[1])
		return o ? json(res, 200, o) : json(res, 404, { message: 'Order not found' })
	}

	// ----- cart -----
	if (p === '/api/cart') {
		const c = [...carts.values()].find((x) => x.userId === user.id && authed(req))
		return json(res, 200, c ? cartView(c) : {})
	}
	if (p === '/api/carts' && m === 'POST') {
		const c = newCart(authed(req) ? user.id : null)
		return json(res, 200, cartView(c))
	}
	if ((mm = p.match(/^\/api\/carts\/refresh\/([^/]+)$/))) {
		let c = carts.get(mm[1])
		if (!c && authed(req)) c = savedCart
		return json(res, 200, c ? cartView(c) : {})
	}
	if ((mm = p.match(/^\/api\/carts\/([^/]+)\/line-items(?:\/([^/]+))?$/))) {
		const c = carts.get(mm[1]) || newCart(null)
		if (m === 'DELETE') c.lines = c.lines.filter((l) => l.id !== mm[2])
		else {
			const lineId = mm[2] || body.id
			let l = c.lines.find((x) => x.id === lineId) || c.lines.find((x) => x.variantId === body.variantId && !lineId)
			const prod = products.find((x) => x.id === body.productId)
			if (l) { l.qty = mm[2] || body.id ? Number(body.qty) : l.qty + Number(body.qty || 1) }
			else if (prod) c.lines.push((l = { id: 'line_' + crypto.randomBytes(4).toString('hex'), productId: prod.id, variantId: body.variantId || prod.variants[0].id, qty: Number(body.qty || 1) }))
			c.lines = c.lines.filter((x) => x.qty > 0)
		}
		return json(res, 200, cartView(c))
	}
	if ((mm = p.match(/^\/api\/cart\/(apply|remove)-coupon\/([^/]+)$/))) {
		const c = carts.get(mm[2])
		if (!c) return json(res, 404, { message: 'Cart not found' })
		if (mm[1] === 'apply') {
			const cpn = db.coupons.find((x) => x.code.toLowerCase() === String(body.couponCode || '').toLowerCase())
			if (!cpn) return json(res, 400, { message: 'This coupon code is not valid' })
			c.couponCode = cpn.code
		} else c.couponCode = null
		return json(res, 200, cartView(c))
	}
	if ((mm = p.match(/^\/api\/shipping-rates\/([^/]+)$/))) {
		return json(res, 200, list([
			{ id: 'sr_standard', name: 'Standard (3–6 business days)', price: 0, rate: 0, estimatedMinDays: 3, estimatedMaxDays: 6 },
			{ id: 'sr_express', name: 'Express (1–2 business days)', price: 18.5, rate: 18.5, estimatedMinDays: 1, estimatedMaxDays: 2 }
		]))
	}
	if ((mm = p.match(/^\/api\/carts\/([^/]+)\/complete$/)) || (mm = p.match(/^\/api\/carts\/([^/]+)\/payment-sessions$/))) {
		const c = carts.get(mm[1])
		return json(res, 200, { ...cartView(c || newCart(null)), orderNo: 'NF-25201', order_no: 'NF-25201' })
	}
	if ((mm = p.match(/^\/api\/carts\/([^/]+)$/))) {
		let c = carts.get(mm[1])
		if (!c && authed(req)) c = savedCart
		if (!c) return json(res, 404, { message: 'Cart not found' })
		if (m === 'PATCH' || m === 'POST') Object.assign(c, body)
		return json(res, 200, cartView(c))
	}
	if (p.startsWith('/api/checkout/')) {
		const no = 'NF-25201'
		return json(res, 200, { orderNo: no, order_no: no, id: 'ord_' + no, status: 'Pending', paymentStatus: 'pending', redirectUrl: `/checkout/success?order_no=${no}` })
	}
	if (p === '/api/coupons') return json(res, 200, list(db.coupons))
	if ((mm = p.match(/^\/api\/coupons\/([^/]+)$/))) return json(res, 200, db.coupons.find((c) => c.id === mm[1] || c.code === mm[1]) || {})
	if (p === '/api/chats') return json(res, 200, list([]))
	if (p === '/api/dashboard/summary') return json(res, 200, {})
	if (p === '/api/newsletter/subscribe') return json(res, 200, { success: true, message: 'You are on the list — look out for the Thursday letter.' })
	if (p === '/api/shipping-zones') return json(res, 200, list([{ id: 'sz_us', name: 'Contiguous US', countries: ['US'], rates: [{ id: 'sr_standard', name: 'Standard (3–6 business days)', price: 7.95, freeAbove: 75 }, { id: 'sr_express', name: 'Express (1–2 business days)', price: 18.5 }] }]))
	if (p === '/api/collections/all-ratings' || p === '/api/vendors/all-ratings') return json(res, 200, { data: [], count: 0, avgRating: 0 })
	if (p === '/api/vendors/me') return json(res, 404, { message: 'This account is not a vendor' })
	if (p === '/api/admin/auth/change-password') return json(res, 200, { success: true, message: 'Password updated' })
	if (p === '/api/upload' || p === '/api/upload/multiple') return json(res, 200, { url: IMG_FALLBACK, urls: [IMG_FALLBACK], data: [{ url: IMG_FALLBACK }] })
	if (p === '/api/upload/delete') return json(res, 200, { success: true })
	if (p.startsWith('/api/delete/user')) return json(res, 200, { success: true, message: 'Your account deletion request has been received.' })
	if (p === '/api/varni-custom-design') return json(res, 200, { success: true, message: 'Thanks — our team will be in touch.' })
	if (p === '/api/affirm-checkout/create-order') return json(res, 200, { orderNo: 'NF-25201', order_no: 'NF-25201', redirectUrl: '/checkout/success?order_no=NF-25201' })
	if (p === '/api/admin/users' || p === '/api/users') return json(res, 200, m === 'GET' ? list([publicUser()]) : publicUser())

	// ----- Conversational Shopping assistant (/api/commerce-assistant/*) -----
	// Northfield has the advisor switched off in its admin (the storefront widget's built-in prompts
	// are written for a jewellery store), so config reports enabled:false and the widget stays hidden.
	// STUB_ASSISTANT=on flips the toggle; the session/message routes below then answer from the catalog.
	if (p === '/api/commerce-assistant/config') return json(res, 200, { enabled: process.env.STUB_ASSISTANT === 'on', currency: 'USD', maxRecommendations: 3 })
	if (p === '/api/commerce-assistant/sessions' && m === 'POST') {
		const sessionId = 'cas_' + crypto.randomBytes(8).toString('hex')
		return json(res, 200, { sessionId, anonymousId: body.anonymousId || null, currency: 'USD', locale: body.locale || 'en-US' })
	}
	if ((mm = p.match(/^\/api\/commerce-assistant\/sessions\/([^/]+)\/messages$/))) return json(res, 200, assistantReply(String(body.message || '')))
	if ((mm = p.match(/^\/api\/commerce-assistant\/sessions\/([^/]+)\/add-to-cart$/))) {
		const prod = products.find((x) => x.id === body.productId)
		const v = prod?.variants.find((x) => x.id === body.variantId)
		if (!prod || !v) return json(res, 200, { valid: false, reason: 'That item is no longer available.', reasonCode: 'NOT_FOUND' })
		if (v.stock <= 0) return json(res, 200, { valid: false, reason: `${prod.title} is sold out right now.`, reasonCode: 'OUT_OF_STOCK' })
		return json(res, 200, { valid: true, item: { productId: prod.id, variantId: v.id, qty: Number(body.qty || 1), title: prod.title, price: v.price } })
	}
	if ((mm = p.match(/^\/api\/commerce-assistant\/sessions\/([^/]+)\/events$/))) return json(res, 200, { ok: true })

	console.log('[stub] unhandled', m, req.url)
	return json(res, 404, { message: `Not found: ${p}` })
})
server.listen(PORT, '127.0.0.1', () => console.log(`[stub] Litekart API stub on http://127.0.0.1:${PORT}`))
